[
  {
    "source_url": "https://ethereum.github.io/consensus-specs/specs/fulu/polynomial-commitments-sampling/",
    "title": "Fulu -- Polynomial Commitments Sampling",
    "category": "consensus-spec",
    "type": "Specification",
    "layer": "consensus/cryptography",
    "sub_graphs": [
      {
        "id": "SG-PCS-001",
        "name": "Types and Presets",
        "description": "Defines core types (Cell, CellIndex, CommitmentIndex) and cryptographic types (PolynomialCoeff, Coset, CosetEvals) used in DAS polynomial commitment sampling. Also defines preset constants governing blob extension and cell structure.",
        "invariants": [
          {"id": "INV-PCS-001", "text": "CellIndex must satisfy x < CELLS_PER_EXT_BLOB."},
          {"id": "INV-PCS-002", "text": "FIELD_ELEMENTS_PER_EXT_BLOB = 2 * FIELD_ELEMENTS_PER_BLOB (Reed-Solomon extension doubles the field elements)."},
          {"id": "INV-PCS-003", "text": "FIELD_ELEMENTS_PER_CELL = 64 (fixed cell size)."},
          {"id": "INV-PCS-004", "text": "CELLS_PER_EXT_BLOB = FIELD_ELEMENTS_PER_EXT_BLOB / FIELD_ELEMENTS_PER_CELL."},
          {"id": "INV-PCS-005", "text": "BYTES_PER_CELL = FIELD_ELEMENTS_PER_CELL * BYTES_PER_FIELD_ELEMENT."},
          {"id": "INV-PCS-006", "text": "Cell is ByteVector[BYTES_PER_FIELD_ELEMENT * FIELD_ELEMENTS_PER_CELL]."}
        ],
        "functions": [],
        "state_variables": [
          {"id": "SV-PCS-001", "name": "FIELD_ELEMENTS_PER_EXT_BLOB", "type": "uint64", "description": "2 * FIELD_ELEMENTS_PER_BLOB"},
          {"id": "SV-PCS-002", "name": "FIELD_ELEMENTS_PER_CELL", "type": "uint64", "description": "64"},
          {"id": "SV-PCS-003", "name": "BYTES_PER_CELL", "type": "uint64", "description": "FIELD_ELEMENTS_PER_CELL * BYTES_PER_FIELD_ELEMENT"},
          {"id": "SV-PCS-004", "name": "CELLS_PER_EXT_BLOB", "type": "uint64", "description": "FIELD_ELEMENTS_PER_EXT_BLOB // FIELD_ELEMENTS_PER_CELL"},
          {"id": "SV-PCS-005", "name": "RANDOM_CHALLENGE_KZG_CELL_BATCH_DOMAIN", "type": "bytes", "description": "b'RCKZGCBATCH__V1_'"}
        ],
        "data_structures": [
          {"id": "DS-PCS-001", "name": "Cell", "definition": "ByteVector[BYTES_PER_FIELD_ELEMENT * FIELD_ELEMENTS_PER_CELL]"},
          {"id": "DS-PCS-002", "name": "CellIndex", "definition": "uint64"},
          {"id": "DS-PCS-003", "name": "CommitmentIndex", "definition": "uint64"},
          {"id": "DS-PCS-004", "name": "PolynomialCoeff", "definition": "List[BLSFieldElement, FIELD_ELEMENTS_PER_EXT_BLOB]"},
          {"id": "DS-PCS-005", "name": "Coset", "definition": "Vector[BLSFieldElement, FIELD_ELEMENTS_PER_CELL]"},
          {"id": "DS-PCS-006", "name": "CosetEvals", "definition": "Vector[BLSFieldElement, FIELD_ELEMENTS_PER_CELL]"}
        ]
      },
      {
        "id": "SG-PCS-002",
        "name": "BLS12-381 Helpers (Cell/Coset Conversion)",
        "description": "Helper functions for converting between Cell (untrusted bytes) and CosetEvals (trusted field elements). These are the serialization/deserialization boundary for cell data.",
        "invariants": [
          {"id": "INV-PCS-007", "text": "cell_to_coset_evals and coset_evals_to_cell are inverse operations: coset_evals_to_cell(cell_to_coset_evals(cell)) == cell."},
          {"id": "INV-PCS-008", "text": "Each field element in a cell is exactly BYTES_PER_FIELD_ELEMENT bytes."}
        ],
        "functions": [
          {"id": "FN-PCS-001", "signature": "cell_to_coset_evals(cell: Cell) -> CosetEvals", "description": "Convert an untrusted Cell into a trusted CosetEvals by deserializing each field element via bytes_to_bls_field."},
          {"id": "FN-PCS-002", "signature": "coset_evals_to_cell(coset_evals: CosetEvals) -> Cell", "description": "Convert a trusted CosetEvals into an untrusted Cell by serializing each field element via bls_field_to_bytes."}
        ],
        "state_variables": [],
        "data_structures": []
      },
      {
        "id": "SG-PCS-003",
        "name": "FFT Helpers",
        "description": "Fast Fourier Transform operations over BLS12-381 field elements. Includes recursive FFT, inverse FFT, and coset FFT for polynomial evaluation/interpolation in the DAS scheme.",
        "invariants": [
          {"id": "INV-PCS-009", "text": "FFT input length must be a power of 2."},
          {"id": "INV-PCS-010", "text": "fft_field with inv=True is the inverse of fft_field with inv=False."},
          {"id": "INV-PCS-011", "text": "Coset FFT uses PRIMITIVE_ROOT_OF_UNITY as the shift factor to avoid vanishing polynomial zeros in the evaluation domain."}
        ],
        "functions": [
          {"id": "FN-PCS-003", "signature": "_fft_field(vals: Sequence[BLSFieldElement], roots_of_unity: Sequence[BLSFieldElement]) -> Sequence[BLSFieldElement]", "description": "Recursive Cooley-Tukey FFT over BLS field elements."},
          {"id": "FN-PCS-004", "signature": "fft_field(vals: Sequence[BLSFieldElement], roots_of_unity: Sequence[BLSFieldElement], inv: bool = False) -> Sequence[BLSFieldElement]", "description": "FFT or inverse FFT over BLS field elements."},
          {"id": "FN-PCS-005", "signature": "coset_fft_field(vals: Sequence[BLSFieldElement], roots_of_unity: Sequence[BLSFieldElement], inv: bool = False) -> Sequence[BLSFieldElement]", "description": "FFT/IFFT over a coset of the roots of unity, useful for dividing by vanishing polynomials."}
        ],
        "state_variables": [],
        "data_structures": []
      },
      {
        "id": "SG-PCS-004",
        "name": "Fiat-Shamir Challenge Generation",
        "description": "Computes a deterministic random challenge for the universal batch cell KZG proof verification using Fiat-Shamir heuristic. Hashes all prover-provided data to derive a random field element.",
        "invariants": [
          {"id": "INV-PCS-012", "text": "The challenge is deterministic: same inputs always produce the same challenge r."},
          {"id": "INV-PCS-013", "text": "All data that can influence the verification (commitments, indices, evaluations, proofs) must be included in the hash input."},
          {"id": "INV-PCS-014", "text": "Domain separation is enforced via RANDOM_CHALLENGE_KZG_CELL_BATCH_DOMAIN prefix."}
        ],
        "functions": [
          {"id": "FN-PCS-006", "signature": "compute_verify_cell_kzg_proof_batch_challenge(commitments, commitment_indices, cell_indices, cosets_evals, proofs) -> BLSFieldElement", "description": "Compute a random challenge r used in the universal verification equation via Fiat-Shamir heuristic."}
        ],
        "state_variables": [],
        "data_structures": []
      },
      {
        "id": "SG-PCS-005",
        "name": "Polynomial Coefficient Form Operations",
        "description": "Arithmetic operations on polynomials in coefficient form, including conversion from evaluation form, addition, multiplication, division, interpolation, vanishing polynomial computation, and Horner evaluation.",
        "invariants": [
          {"id": "INV-PCS-015", "text": "multiply_polynomialcoeff requires len(a) + len(b) <= FIELD_ELEMENTS_PER_EXT_BLOB."},
          {"id": "INV-PCS-016", "text": "interpolate_polynomialcoeff requires len(xs) == len(ys)."},
          {"id": "INV-PCS-017", "text": "vanishing_polynomialcoeff(xs) evaluates to zero at every x in xs."},
          {"id": "INV-PCS-018", "text": "polynomial_eval_to_coeff uses inverse FFT with bit-reversal permutation to convert evaluation form to coefficient form."}
        ],
        "functions": [
          {"id": "FN-PCS-007", "signature": "polynomial_eval_to_coeff(polynomial: Polynomial) -> PolynomialCoeff", "description": "Interpolate a polynomial from evaluation form to coefficient form using inverse FFT."},
          {"id": "FN-PCS-008", "signature": "add_polynomialcoeff(a: PolynomialCoeff, b: PolynomialCoeff) -> PolynomialCoeff", "description": "Sum two coefficient form polynomials."},
          {"id": "FN-PCS-009", "signature": "multiply_polynomialcoeff(a: PolynomialCoeff, b: PolynomialCoeff) -> PolynomialCoeff", "description": "Multiply two coefficient form polynomials."},
          {"id": "FN-PCS-010", "signature": "divide_polynomialcoeff(a: PolynomialCoeff, b: PolynomialCoeff) -> PolynomialCoeff", "description": "Long polynomial division for two coefficient form polynomials."},
          {"id": "FN-PCS-011", "signature": "interpolate_polynomialcoeff(xs, ys) -> PolynomialCoeff", "description": "Lagrange interpolation to find the lowest degree polynomial matching given points."},
          {"id": "FN-PCS-012", "signature": "vanishing_polynomialcoeff(xs) -> PolynomialCoeff", "description": "Compute the vanishing polynomial on xs in coefficient form."},
          {"id": "FN-PCS-013", "signature": "evaluate_polynomialcoeff(polynomial_coeff, z) -> BLSFieldElement", "description": "Evaluate a coefficient form polynomial at z using Horner's schema."}
        ],
        "state_variables": [],
        "data_structures": []
      },
      {
        "id": "SG-PCS-006",
        "name": "KZG Multiproofs",
        "description": "Compute and verify KZG multi-evaluation proofs for sets of points. The compute function creates quotient polynomials Q(X) = f(X)/Z(X), and the verify function implements the universal verification equation using pairings.",
        "invariants": [
          {"id": "INV-PCS-019", "text": "compute_kzg_proof_multi_impl: The quotient polynomial Q(X) = f(X) / Z(X) where Z(X) vanishes on all evaluation points."},
          {"id": "INV-PCS-020", "text": "verify_cell_kzg_proof_batch_impl: len(commitment_indices) == len(cell_indices) == len(cosets_evals) == len(proofs)."},
          {"id": "INV-PCS-021", "text": "verify_cell_kzg_proof_batch_impl: commitments list contains no duplicates."},
          {"id": "INV-PCS-022", "text": "verify_cell_kzg_proof_batch_impl: each commitment_index < len(commitments)."},
          {"id": "INV-PCS-023", "text": "Verification equation: pairing(LL, LR) == pairing(RL, [1]) where LL = sum_k r^k proofs[k], LR = [s^n], RL = RLC - RLI + RLP."}
        ],
        "functions": [
          {"id": "FN-PCS-014", "signature": "compute_kzg_proof_multi_impl(polynomial_coeff: PolynomialCoeff, zs: Coset) -> Tuple[KZGProof, CosetEvals]", "description": "Compute a KZG multi-evaluation proof for a set of k points using quotient polynomial."},
          {"id": "FN-PCS-015", "signature": "verify_cell_kzg_proof_batch_impl(commitments, commitment_indices, cell_indices, cosets_evals, proofs) -> bool", "description": "Verify that a set of cells belong to their corresponding commitment using universal verification equation with pairings."}
        ],
        "state_variables": [],
        "data_structures": []
      },
      {
        "id": "SG-PCS-007",
        "name": "Cell Cosets",
        "description": "Functions to compute the evaluation domain (coset) for each cell. Each cell is evaluated over a distinct coset of the roots of unity, determined by bit-reversal permutation.",
        "invariants": [
          {"id": "INV-PCS-024", "text": "cell_index must be < CELLS_PER_EXT_BLOB."},
          {"id": "INV-PCS-025", "text": "Each cell's coset is a distinct subset of FIELD_ELEMENTS_PER_CELL consecutive elements from the bit-reversal permuted roots of unity."},
          {"id": "INV-PCS-026", "text": "coset_shift_for_cell returns the generator h such that the coset is h * G where G is the subgroup of order FIELD_ELEMENTS_PER_CELL."}
        ],
        "functions": [
          {"id": "FN-PCS-016", "signature": "coset_shift_for_cell(cell_index: CellIndex) -> BLSFieldElement", "description": "Get the shift h that determines the coset for a given cell_index."},
          {"id": "FN-PCS-017", "signature": "coset_for_cell(cell_index: CellIndex) -> Coset", "description": "Get the full coset (evaluation domain) for a given cell_index."}
        ],
        "state_variables": [],
        "data_structures": []
      },
      {
        "id": "SG-PCS-008",
        "name": "Cell Computation (Public Methods)",
        "description": "Public methods for computing cells and KZG proofs from blobs. Converts blob to polynomial in coefficient form, then evaluates over each cell's coset to produce cells and proofs.",
        "invariants": [
          {"id": "INV-PCS-027", "text": "compute_cells and compute_cells_and_kzg_proofs require len(blob) == BYTES_PER_BLOB."},
          {"id": "INV-PCS-028", "text": "Output contains exactly CELLS_PER_EXT_BLOB cells and CELLS_PER_EXT_BLOB proofs."},
          {"id": "INV-PCS-029", "text": "The algorithm is O(n^2); production implementations should use FK20 for O(n log n)."}
        ],
        "functions": [
          {"id": "FN-PCS-018", "signature": "compute_cells(blob: Blob) -> Vector[Cell, CELLS_PER_EXT_BLOB]", "description": "Given a blob, extend it and return all cells of the extended blob. Public method."},
          {"id": "FN-PCS-019", "signature": "compute_cells_and_kzg_proofs_polynomialcoeff(polynomial_coeff: PolynomialCoeff) -> Tuple[Vector[Cell, CELLS_PER_EXT_BLOB], Vector[KZGProof, CELLS_PER_EXT_BLOB]]", "description": "Helper function computing cells/proofs for a polynomial in coefficient form."},
          {"id": "FN-PCS-020", "signature": "compute_cells_and_kzg_proofs(blob: Blob) -> Tuple[Vector[Cell, CELLS_PER_EXT_BLOB], Vector[KZGProof, CELLS_PER_EXT_BLOB]]", "description": "Compute all cell proofs for an extended blob. Public method."}
        ],
        "state_variables": [],
        "data_structures": []
      },
      {
        "id": "SG-PCS-009",
        "name": "Cell Verification (Public Method)",
        "description": "Public method for batch verification of cells against commitments using the universal verification equation. Handles deduplication of commitments and delegates to the internal implementation.",
        "invariants": [
          {"id": "INV-PCS-030", "text": "len(commitments_bytes) == len(cells) == len(proofs_bytes) == len(cell_indices)."},
          {"id": "INV-PCS-031", "text": "Each commitment_bytes must be BYTES_PER_COMMITMENT in length."},
          {"id": "INV-PCS-032", "text": "Each cell_index must be < CELLS_PER_EXT_BLOB."},
          {"id": "INV-PCS-033", "text": "Each cell must be BYTES_PER_CELL in length."},
          {"id": "INV-PCS-034", "text": "Each proof_bytes must be BYTES_PER_PROOF in length."},
          {"id": "INV-PCS-035", "text": "Commitments are deduplicated before passing to internal verification, with commitment_indices mapping back to the original list."}
        ],
        "functions": [
          {"id": "FN-PCS-021", "signature": "verify_cell_kzg_proof_batch(commitments_bytes, cell_indices, cells, proofs_bytes) -> bool", "description": "Verify that a set of cells belong to their corresponding commitments using the universal verification equation. Public method."}
        ],
        "state_variables": [],
        "data_structures": []
      },
      {
        "id": "SG-PCS-010",
        "name": "Cell Reconstruction (Public Method)",
        "description": "Recovery of all cells and KZG proofs from at least 50% of available cells using Reed-Solomon erasure coding. Constructs vanishing polynomial over missing cells, performs polynomial division via coset FFT to avoid division by zero.",
        "invariants": [
          {"id": "INV-PCS-036", "text": "recover_cells_and_kzg_proofs requires len(cell_indices) == len(cells)."},
          {"id": "INV-PCS-037", "text": "At least CELLS_PER_EXT_BLOB / 2 cells must be available for recovery."},
          {"id": "INV-PCS-038", "text": "At most CELLS_PER_EXT_BLOB cells can be provided."},
          {"id": "INV-PCS-039", "text": "No duplicate cell_indices allowed."},
          {"id": "INV-PCS-040", "text": "cell_indices must be in ascending order."},
          {"id": "INV-PCS-041", "text": "All cell_indices must be < CELLS_PER_EXT_BLOB."},
          {"id": "INV-PCS-042", "text": "All cells must have length BYTES_PER_CELL."},
          {"id": "INV-PCS-043", "text": "construct_vanishing_polynomial assumes not all cells are missing (at least half must be present)."},
          {"id": "INV-PCS-044", "text": "recover_polynomialcoeff output is truncated to FIELD_ELEMENTS_PER_BLOB coefficients (the original blob polynomial degree)."},
          {"id": "INV-PCS-045", "text": "Division by vanishing polynomial is performed over a coset of the FFT domain to avoid division by zero."}
        ],
        "functions": [
          {"id": "FN-PCS-022", "signature": "construct_vanishing_polynomial(missing_cell_indices: Sequence[CellIndex]) -> Sequence[BLSFieldElement]", "description": "Compute the polynomial vanishing at every point corresponding to missing field elements, extended to full domain."},
          {"id": "FN-PCS-023", "signature": "recover_polynomialcoeff(cell_indices, cosets_evals) -> PolynomialCoeff", "description": "Recover the polynomial in coefficient form from available cell evaluations using FFT-based Reed-Solomon recovery."},
          {"id": "FN-PCS-024", "signature": "recover_cells_and_kzg_proofs(cell_indices, cells) -> Tuple[Vector[Cell, CELLS_PER_EXT_BLOB], Vector[KZGProof, CELLS_PER_EXT_BLOB]]", "description": "Given at least 50% of cells, recover all cells/proofs using FFT-based erasure code recovery. Public method."}
        ],
        "state_variables": [],
        "data_structures": []
      }
    ],
    "metadata": {
      "timestamp": "1770265501",
      "extraction_method": "manual_analysis",
      "public_methods": ["compute_cells_and_kzg_proofs", "verify_cell_kzg_proof_batch", "recover_cells_and_kzg_proofs"],
      "total_subgraphs": 10,
      "total_invariants": 45,
      "total_functions": 24
    }
  },
  {
    "source_url": "https://ethereum.github.io/consensus-specs/specs/fulu/validator/",
    "title": "Fulu -- Honest Validator",
    "category": "consensus-spec",
    "type": "Specification",
    "layer": "consensus",
    "sub_graphs": [
      {
        "id": "SG-VAL-001",
        "name": "Custody Configuration",
        "description": "Defines custody-related configuration constants that determine the minimum number of custody groups validators must custody and serve, and the balance threshold for additional custody.",
        "invariants": [
          {"id": "INV-VAL-001", "text": "VALIDATOR_CUSTODY_REQUIREMENT = 8 (minimum custody groups for any node with validators)."},
          {"id": "INV-VAL-002", "text": "BALANCE_PER_ADDITIONAL_CUSTODY_GROUP = 32 ETH (Gwei(32 * 10^9))."},
          {"id": "INV-VAL-003", "text": "Custody group count is bounded: VALIDATOR_CUSTODY_REQUIREMENT <= custody_groups <= NUMBER_OF_CUSTODY_GROUPS."}
        ],
        "functions": [],
        "state_variables": [
          {"id": "SV-VAL-001", "name": "VALIDATOR_CUSTODY_REQUIREMENT", "type": "uint64", "description": "8"},
          {"id": "SV-VAL-002", "name": "BALANCE_PER_ADDITIONAL_CUSTODY_GROUP", "type": "Gwei", "description": "32 * 10^9"}
        ],
        "data_structures": []
      },
      {
        "id": "SG-VAL-002",
        "name": "Modified BlobsBundle and GetPayloadResponse",
        "description": "Modified data structures for Fulu (EIP-7594). BlobsBundle now contains cell KZG proofs instead of blob KZG proofs, with proofs list sized to FIELD_ELEMENTS_PER_EXT_BLOB * MAX_BLOB_COMMITMENTS_PER_BLOCK.",
        "invariants": [
          {"id": "INV-VAL-004", "text": "BlobsBundle.proofs list length is FIELD_ELEMENTS_PER_EXT_BLOB * MAX_BLOB_COMMITMENTS_PER_BLOCK (cell-level proofs instead of blob-level)."},
          {"id": "INV-VAL-005", "text": "BlobsBundle.commitments length is MAX_BLOB_COMMITMENTS_PER_BLOCK."},
          {"id": "INV-VAL-006", "text": "BlobsBundle.blobs length is MAX_BLOB_COMMITMENTS_PER_BLOCK."}
        ],
        "functions": [
          {"id": "FN-VAL-001", "signature": "get_payload(self: ExecutionEngine, payload_id: PayloadId) -> GetPayloadResponse", "description": "Return ExecutionPayload, uint256, BlobsBundle objects. Modified to return updated BlobsBundle with cell KZG proofs."}
        ],
        "state_variables": [],
        "data_structures": [
          {"id": "DS-VAL-001", "name": "BlobsBundle", "definition": "@dataclass with commitments: List[KZGCommitment, MAX_BLOB_COMMITMENTS_PER_BLOCK], proofs: List[KZGProof, FIELD_ELEMENTS_PER_EXT_BLOB * MAX_BLOB_COMMITMENTS_PER_BLOCK], blobs: List[Blob, MAX_BLOB_COMMITMENTS_PER_BLOCK]"},
          {"id": "DS-VAL-002", "name": "GetPayloadResponse", "definition": "@dataclass with execution_payload: ExecutionPayload, block_value: uint256, blobs_bundle: BlobsBundle, execution_requests: Sequence[bytes]"}
        ]
      },
      {
        "id": "SG-VAL-003",
        "name": "Validator Custody Requirement Calculation",
        "description": "Computes the required number of custody groups for a node based on the total effective balance of all attached validators. Scales linearly with balance, bounded by minimum (VALIDATOR_CUSTODY_REQUIREMENT) and maximum (NUMBER_OF_CUSTODY_GROUPS).",
        "invariants": [
          {"id": "INV-VAL-007", "text": "get_validators_custody_requirement returns min(max(total_balance // BALANCE_PER_ADDITIONAL_CUSTODY_GROUP, VALIDATOR_CUSTODY_REQUIREMENT), NUMBER_OF_CUSTODY_GROUPS)."},
          {"id": "INV-VAL-008", "text": "A node SHOULD dynamically adjust custody groups following changes to total effective balances of attached validators."},
          {"id": "INV-VAL-009", "text": "If custody requirements decrease, the node SHOULD NOT reduce its custody_group_count; it SHOULD maintain the previous highest count."},
          {"id": "INV-VAL-010", "text": "The previous highest custody_group_count SHOULD persist across node restarts."},
          {"id": "INV-VAL-011", "text": "When custody_group_count is updated, earliest_available_slot in status RPC SHOULD reflect the update slot."}
        ],
        "functions": [
          {"id": "FN-VAL-002", "signature": "get_validators_custody_requirement(state: BeaconState, validator_indices: Sequence[ValidatorIndex]) -> uint64", "description": "Compute minimum custody groups for a node based on total effective balance of attached validators, bounded by VALIDATOR_CUSTODY_REQUIREMENT and NUMBER_OF_CUSTODY_GROUPS."}
        ],
        "state_variables": [],
        "data_structures": []
      },
      {
        "id": "SG-VAL-004",
        "name": "DataColumnSidecar Construction",
        "description": "Functions to construct DataColumnSidecars from blocks and blob data. Sidecars are vertical slices of all blobs stacked, containing one column of cells across all blobs with associated proofs and commitments.",
        "invariants": [
          {"id": "INV-VAL-012", "text": "len(cells_and_kzg_proofs) == len(kzg_commitments) (one cell/proof set per blob)."},
          {"id": "INV-VAL-013", "text": "Exactly NUMBER_OF_COLUMNS sidecars are produced, one per column index."},
          {"id": "INV-VAL-014", "text": "Each sidecar contains one cell per blob for its column_index."},
          {"id": "INV-VAL-015", "text": "Cell proofs in BlobsBundle are indexed as blobs_bundle.proofs[i * CELLS_PER_EXT_BLOB : (i+1) * CELLS_PER_EXT_BLOB] for blob i."}
        ],
        "functions": [
          {"id": "FN-VAL-003", "signature": "get_data_column_sidecars(signed_block_header, kzg_commitments, kzg_commitments_inclusion_proof, cells_and_kzg_proofs) -> Sequence[DataColumnSidecar]", "description": "Given a signed block header and commitments, inclusion proof, cells/proofs for each blob, assemble sidecars for peer distribution."},
          {"id": "FN-VAL-004", "signature": "get_data_column_sidecars_from_block(signed_block, cells_and_kzg_proofs) -> Sequence[DataColumnSidecar]", "description": "Given a signed block and cells/proofs, compute signed_block_header and inclusion proof, then assemble sidecars."},
          {"id": "FN-VAL-005", "signature": "get_data_column_sidecars_from_column_sidecar(sidecar, cells_and_kzg_proofs) -> Sequence[DataColumnSidecar]", "description": "Reconstruct all sidecars from any single sidecar and all cells/proofs. Used in distributed blob publishing."}
        ],
        "state_variables": [],
        "data_structures": [
          {"id": "DS-VAL-003", "name": "DataColumnSidecar", "definition": "Container with index (column_index), column (cells for this column across all blobs), kzg_commitments, kzg_proofs, signed_block_header, kzg_commitments_inclusion_proof"}
        ]
      },
      {
        "id": "SG-VAL-005",
        "name": "Sidecar Publishing and Retention",
        "description": "Rules for publishing DataColumnSidecars to the network and retention requirements. Sidecars are published to data_column_sidecar_{subnet_id} pubsub topics.",
        "invariants": [
          {"id": "INV-VAL-016", "text": "subnet_id = compute_subnet_for_data_column_sidecar(column_index) determines the pubsub topic."},
          {"id": "INV-VAL-017", "text": "Validators MUST retain sidecars for MIN_EPOCHS_FOR_DATA_COLUMN_SIDECARS_REQUESTS epochs."},
          {"id": "INV-VAL-018", "text": "After MIN_EPOCHS_FOR_DATA_COLUMN_SIDECARS_REQUESTS epochs, nodes MAY prune sidecars."},
